class _AioClient:
    async def __aenter__(self):
        return self

    async def __aexit__(self, *args):
        return None

    async def get_object(self, *args, **kwargs):
        return {}

    async def list_objects_v2(self, *args, **kwargs):
        return {}


class Session:
    def client(self, *args, **kwargs):
        return _AioClient()

    def resource(self, *args, **kwargs):
        return _AioClient()
